#!/usr/bin/env node
// Distill a captured conversation JSONL into a readable trace.
import { readFileSync } from 'node:fs';

const [file, mode = 'full'] = process.argv.slice(2);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

const clip = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ' …[+' + (s.length - n) + ']' : s;
};

let t0 = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.ts || null;
  const tt = ts ? new Date(ts) : null;
  if (tt && !t0) t0 = tt;
  const rel = tt && t0 ? '+' + String(Math.round((tt - t0) / 1000)).padStart(5) + 's' : '      ';
  const msg = e.message || e;
  const role = e.type || msg.role || '?';
  const content = msg.content;
  const usage = msg.usage ? ` [in=${msg.usage.input_tokens ?? 0} cache=${msg.usage.cache_read_input_tokens ?? 0} out=${msg.usage.output_tokens ?? 0}]` : '';
  if (typeof content === 'string') {
    console.log(`${rel} ${role}${usage}: ${clip(content, mode === 'full' ? 3000 : 400)}`);
    continue;
  }
  if (!Array.isArray(content)) { console.log(`${rel} ${role}${usage}: ${clip(JSON.stringify(msg), 300)}`); continue; }
  for (const b of content) {
    if (b.type === 'text') console.log(`${rel} ${role}${usage}: ${clip(b.text, mode === 'full' ? 3000 : 400)}`);
    else if (b.type === 'thinking') console.log(`${rel} ${role} THINK: ${clip(b.thinking, mode === 'full' ? 900 : 200)}`);
    else if (b.type === 'tool_use') console.log(`${rel} TOOL ${b.name}(${clip(JSON.stringify(b.input), 400)})`);
    else if (b.type === 'tool_result') {
      const c = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
      console.log(`${rel}   -> ${b.is_error ? 'ERROR ' : ''}${clip(c, 300)}`);
    } else console.log(`${rel} ${role} ${b.type}`);
  }
}

